gnals</h2><div class="s10-checks"><?php foreach($checks as $c):?><div class="s10-check <?= $c[2]?'good':'warn' ?>"><div><b><?= backup_step18_h($c[0]) ?></b><span><?= backup_step18_h($c[1]) ?></span></div><strong><?= $c[2]?'PASS':'REVIEW' ?></strong></div><?php endforeach;?></div></aside></section><div class="os-footer-note"><strong>Critical rule:</strong> an encrypted backup is useful only if its passphrase is kept separately and safely. The application cannot recover a forgotten backup passphrase.</div><?php endif;?></main></div></body></html>